const crypto = require('crypto');

/** SHA-256 hex digest — used for refresh tokens & OTP codes at rest. */
const sha256 = (value) => crypto.createHash('sha256').update(value).digest('hex');

const ENCRYPTION_ALGO = 'aes-256-gcm';

const getEncryptionKey = () => {
  const key = process.env.ENCRYPTION_KEY;
  if (!key) {
    if (process.env.NODE_ENV === 'production') throw new Error('ENCRYPTION_KEY is not configured');
    return crypto.createHash('sha256').update('dev_only_insecure_encryption_key').digest();
  }
  // Accepts a 64-char hex string (32 bytes) as generated by `openssl rand -hex 32`.
  return Buffer.from(key, 'hex');
};

/**
 * AES-256-GCM encryption for sensitive at-rest fields (bank account numbers).
 * Output packs iv + authTag + ciphertext as base64, colon-delimited, so it's
 * safely storable in a single TEXT column.
 */
const encryptSensitive = (plaintext) => {
  const key = getEncryptionKey();
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(ENCRYPTION_ALGO, key, iv);
  const ciphertext = Buffer.concat([cipher.update(String(plaintext), 'utf8'), cipher.final()]);
  const authTag = cipher.getAuthTag();
  return [iv.toString('base64'), authTag.toString('base64'), ciphertext.toString('base64')].join(':');
};

const decryptSensitive = (packed) => {
  const [ivB64, authTagB64, ciphertextB64] = packed.split(':');
  const key = getEncryptionKey();
  const decipher = crypto.createDecipheriv(ENCRYPTION_ALGO, key, Buffer.from(ivB64, 'base64'));
  decipher.setAuthTag(Buffer.from(authTagB64, 'base64'));
  const plaintext = Buffer.concat([
    decipher.update(Buffer.from(ciphertextB64, 'base64')),
    decipher.final(),
  ]);
  return plaintext.toString('utf8');
};

/** Masks all but the last 4 characters — e.g. account numbers for display. */
const maskLast4 = (value) => {
  const str = String(value);
  return str.length <= 4 ? str : `${'•'.repeat(str.length - 4)}${str.slice(-4)}`;
};

/** Cryptographically random URL-safe token. */
const randomToken = (bytes = 48) => crypto.randomBytes(bytes).toString('base64url');

/** 6-digit numeric OTP with uniform distribution. */
const generateOtp = () => String(crypto.randomInt(0, 1000000)).padStart(6, '0');

/** Short human-friendly referral code. */
const generateReferralCode = () =>
  crypto.randomBytes(6).toString('base64url').replace(/[-_]/g, 'X').slice(0, 8).toUpperCase();

module.exports = {
  sha256, randomToken, generateOtp, generateReferralCode,
  encryptSensitive, decryptSensitive, maskLast4,
};
